      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-design-studio\",\n  \"version\": \"0.18.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"test\": \"node --test --test-concurrency=1 test/*.mjs\"\n  },\n  \"description\": \"Design workbench in the DeepSeek Harness right sidebar: watch web / app / mini program / poster screens generate on a canvas with device frames, click an element or mark it up with a brush to send it to the chat, open existing HTML pages, tweak design tokens with sliders, compare versions, extract a brand's design system from a site, turn a design into React / Vue / HTML code checked pixel by pixel, export share-ready images and scan to view on your phone.\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/OrderG-X/dsh-design-studio.git\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"preview\",\n    \"frontend\",\n    \"design\"\n  ],\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./auto\": \"./lib/auto.js\",\n    \"./auto/locale/*.json\": \"./locale/auto/*.json\",\n    \"./auto/icon\": \"./icon.svg\",\n    \"./offline\": \"./lib/offline.js\",\n    \"./offline/locale/*.json\": \"./locale/offline/*.json\",\n    \"./offline/icon\": \"./icon.svg\",\n    \"./annotations\": \"./lib/annotations-row.js\",\n    \"./annotations/locale/*.json\": \"./locale/annotations/*.json\",\n    \"./annotations/icon\": \"./icon.svg\",\n    \"./tool\": \"./lib/tool.js\",\n    \"./tool/locale/*.json\": \"./locale/tool/*.json\",\n    \"./tool/icon\": \"./icon.svg\",\n    \"./skill\": \"./lib/skill.js\",\n    \"./skill/locale/*.json\": \"./locale/skill/*.json\",\n    \"./skill/icon\": \"./icon.svg\",\n    \"./preset\": \"./lib/preset.js\",\n    \"./preset/locale/*.json\": \"./locale/preset/*.json\",\n    \"./preset/icon\": \"./icon.svg\",\n    \"./gallery\": \"./lib/gallery/index.js\",\n    \"./package.json\": \"./package.json\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./icon.svg\": \"./icon.svg\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"skills\",\n    \"locale\",\n    \"icon.svg\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"assets/hero-sm.jpg\",\n    \"assets/demo.gif\",\n    \"gallery-seed\"\n  ],\n  \"icon\": \"./icon.svg\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-sidebar-right\"\n      ]\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-tools\": \">=0.1.0-rc.1 <0.2.0-0 || >=0.2.0-rc.1 <0.3.0-0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    }\n  }\n}\n"
